#!/bin/sh
# The pipeline from p. 379, on the log generated by logsort.py (run that first with KEEP_LOG=1, or point this at any
# nginx access log). Works in any POSIX shell, including Git Bash on Windows and macOS/Linux terminals.
LOG=${1:-access.log}
cat "$LOG" |
  awk '{print $7}' |
  sort |
  uniq -c |
  sort -r -n |
  head -n 5
